-- ITAM SBN: inventario filtrado para MySQL/MariaDB/XAMPP
-- Fuente: BASE PATRIMONIAL AL 08-05-2026.xlsx
-- Tipos: monitores, teclados, impresoras, laptops, all in one, CPU y workstations.
-- Registros validos: 24934
-- Filas omitidas por SBN invalido: 1031; duplicados: 401

CREATE DATABASE IF NOT EXISTS itam_sbn CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE itam_sbn;

CREATE TABLE IF NOT EXISTS assets (
id CHAR(36) NOT NULL PRIMARY KEY, sbn VARCHAR(12) NOT NULL UNIQUE, internal_code VARCHAR(100),
asset_type VARCHAR(20) NOT NULL, description VARCHAR(250) NOT NULL, brand VARCHAR(100), model VARCHAR(100),
serial_number VARCHAR(150), executing_unit VARCHAR(30), site VARCHAR(150) NOT NULL, floor VARCHAR(50),
room VARCHAR(250), organizational_unit VARCHAR(150), status VARCHAR(20) NOT NULL, condition VARCHAR(20) NOT NULL,
notes TEXT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version INT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
DELETE FROM assets;
COMMIT;
